"""Write docker_ha_compose_text.go: the literal shell/Python/README text of
backend/agents/docker_ha_compose.py (BOOTSTRAP, the raw-string blocks of
_prepare and the README parts of generate_bundle), extracted with ast so the
Go copy cannot drift by transcription. Run from the repository root:

    python server/internal/installer/testdata/gen_compose_text.py && gofmt -w server/internal/installer/docker_ha_compose_text.go
"""
import ast
import os

ROOT = os.path.dirname(os.path.abspath(__file__))
SOURCE = os.path.join(ROOT, '..', '..', '..', '..', 'backend', 'agents', 'docker_ha_compose.py')
TARGET = os.path.join(ROOT, '..', 'docker_ha_compose_text.go')


def strings(node, minimum):
    found = [n for n in ast.walk(node) if isinstance(n, ast.Constant) and isinstance(n.value, str) and len(n.value) >= minimum]
    return [n.value for n in sorted(found, key=lambda n: (n.lineno, n.col_offset))]


def literal(text):
    assert '\r' not in text and '`' not in text
    return '`' + text + '`'


tree = ast.parse(open(SOURCE, encoding='utf-8').read())
functions = {n.name: n for n in tree.body if isinstance(n, ast.FunctionDef)}
bootstrap = next(n.value.value for n in tree.body if isinstance(n, ast.Assign) and n.targets[0].id == 'BOOTSTRAP')
blocks = strings(functions['_prepare'], 200)
assert len(blocks) == 5, len(blocks)
readme = [s for s in strings(functions['generate_bundle'], 10) if s.startswith(('仅用于', 'NAS ', '。'))]
assert len(readme) == 3, readme
out = ['// Code generated by testdata/gen_compose_text.py from backend/agents/docker_ha_compose.py; DO NOT EDIT.', '',
       'package installer', '',
       '// composeBootstrap is BOOTSTRAP, shipped as bootstrap.py in the Compose bundle.',
       'const composeBootstrap = ' + literal(bootstrap), '',
       '// composePrepareBlocks are the five raw-string blocks of _prepare, in order.',
       'var composePrepareBlocks = [5]string{']
out += ['\t' + literal(b) + ',' for b in blocks]
out += ['}', '', '// composeReadme is README.txt around the project name.',
        'var composeReadme = [3]string{']
out += ['\t' + literal(r) + ',' for r in readme]
out += ['}', '']
with open(TARGET, 'w', encoding='utf-8') as fh:
    fh.write('\n'.join(out))
print('wrote', TARGET)
